WHERE link_to_major = (SELECT major_id FROM major WHERE major_name = 'education') AND position = 'Member';

SELECT CAST(SUM(CASE WHEN T1.type = 'Meeting' THEN T2.cost ELSE 0 END) AS REAL) * 100 / COUNT(T1.event_id) AS percentage_of_meeting_cost
FROM event AS T1
JOIN expense AS T2 ON T1.event_id = T2.link_to_event;

SELECT COUNT(DISTINCT GasStationID) 
FROM gasstations 
WHERE Country = 'CZE' AND Segment = 'Premium';

SELECT AVG(Consumption) / 12 AS AverageMonthlyConsumption
FROM yearmonth
WHERE Date BETWEEN '201301' AND '201312';

SELECT SUM(Consumption) AS TotalConsumption
FROM yearmonth
WHERE Date BETWEEN '201308' AND '201311';

SELECT MAX(Consumption) AS HighestMonthlyConsumption
FROM yearmonth
WHERE STRFTIME('%Y', Date) = '2012';

SELECT AVG(T1.Price * T1.Amount) AS AverageTotalPrice
FROM transactions_1k AS T1
WHERE T1.Date LIKE '2012-01-%';

SELECT COUNT(*) 
FROM transactions_1k 
WHERE Date = '2012-08-26' AND Time < '13:00:00' AND Currency = 'CZK';

SELECT CAST(COUNT(CASE WHEN c.Currency = 'EUR' THEN c.CustomerID END) AS REAL) * 100 / COUNT(c.CustomerID) AS Percentage
FROM customers c
WHERE c.Currency = 'EUR';
